564	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
565	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
566		type pending struct {
567			id  seriesID
568			ref SeriesRef
569			ts  int64
570			val float64
571		}
572	
573		added := 0
574		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
575		seen := make(map[seriesID]map[int64]float64)
576		// 仅记录需要落盘的新增点；校验全部通过后才提交。
577		commits := make([]pending, 0, len(items))
578	
579		failAt := func(index int, msg string) *LineError {
580			return &LineError{Status: "error", Index: index, Error: msg}
581		}
582		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
583			return &LineError{
584				Status: "error",
585				Index:  index,
586				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
587					ref, ts, formatFloat(existing), formatFloat(submitted)),
588				Conflict: &Conflict{
589					// 标签必须复制：冲突结果是本次失败的独立记录，
590					// 调用方修改它不能改动已存序列的身份。
591					Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
592					Timestamp: ts,
593					Existing:  existing,
594					Submitted: submitted,
595				},
596			}
597		}
598	
599		for i, item := range items {
600			pos := i + 1
601			p, err := parseSample(item)
602			if err != nil {
603				return nil, failAt(pos, err.Error())
604			}
605	
606			id := makeSeriesID(p.name, p.labels)
607			ref := SeriesRef{Name: p.name, Labels: p.labels}
608	
609			if byTS, ok := seen[id]; ok {
610				if old, ok := byTS[p.ts]; ok {
611					if old != p.value {
612						return nil, conflictAt(pos, ref, p.ts, old, p.value)
613					}
614					// 同批内重复出现且数值相同：重复，成功忽略。
615					continue
616				}
617			}
618			if sr, ok := s.series[id]; ok {
619				if old, ok := sr.points[p.ts]; ok {
620					if old != p.value {
621						return nil, conflictAt(pos, sr.ref, p.ts, old, p.value)
622					}
623					// 与此前批次已写入的值相同：重复，成功忽略。
624					if seen[id] == nil {
625						seen[id] = map[int64]float64{}
626					}
627					seen[id][p.ts] = p.value
628					continue
629				}
630			}
631	
632			added++
633			if seen[id] == nil {
634				seen[id] = map[int64]float64{}
635			}
636			seen[id][p.ts] = p.value
637			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
638		}
639	
640		// 全部采样点合法且无冲突，原子提交本批新增点。
641		for _, c := range commits {
642			sr := s.series[c.id]
643			if sr == nil {
644				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
645				s.series[c.id] = sr
646			}
647			sr.points[c.ts] = c.val
648		}
649	
650		return s.snapshot(added, len(items)-added), nil
651	}
